update pages set contenu = '{"sections":[{"type":"heros","h1":"Bureau d''étude mécanique : un plan qui tient au montage","mecanisme":"Notre bureau d''étude mécanique dessine au contact de techniciens qui réparent des machines toute l''année. Cadrage, conception, calculs, dossier de fabrication, puis montage et mise en service par les mêmes équipes.","cta":"Faire chiffrer mon étude","telephone":"04 78 33 72 05","phraseDelai":", du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 pendant les phases de réalisation"},{"type":"chiffres","chiffres":[{"valeur":"+ 100","libelle":"collaborateurs · ingénieurs, projeteurs et techniciens salariés, qui conçoivent puis montent sur site."},{"valeur":"+ 120","libelle":"clients industriels · dont plus de 80 qui reviennent chaque année."},{"valeur":"10 %","libelle":"des candidats retenus · entretien technique et entretien comportemental, résultats partagés avec vous."},{"valeur":"4","libelle":"agences · Lyon (siège), Montréal, Dubaï, Madrid, et 10 hubs de techniciens en France."}],"reponse":[{"texte":"<!-- BLOC E01 : bande de chiffres, 4 items -->"}]},{"type":"probleme","punchline":"Un plan dessiné loin de l''atelier finit toujours par se payer au montage.","puces":[{"accroche":"Les idées restent des croquis.","texte":"Un poste à sécuriser, une ligne à modifier, un outillage à remplacer : le sujet attend son tour depuis des mois."},{"accroche":"Les devis fournisseurs sont incomparables.","texte":"Sans cahier des charges écrit, trois offres décrivent trois projets différents."},{"accroche":"Les modifications partent sans calcul","texte":", et la conformité de l''équipement modifié devient votre problème."},{"accroche":"La pièce arrive et ne rentre pas.","texte":"Cote relevée trop vite, accès non vérifié, passage de câble oublié : le montage découvre ce que l''étude n''a pas vu."}]},{"type":"offre","lignes":[{"prestation":"**Cadrage et cahier des charges** : définition du besoin, étude de faisabilité, rédaction, analyse comparée des offres","benefice":"Vos consultations se jouent sur des bases identiques. Le cahier des charges vous protège, y compris si vous confiez la suite à un autre"},{"prestation":"**Conception et modélisation** : avant-projet, conception détaillée, choix des matériaux, des composants et des assemblages","benefice":"L''accès aux organes et l''entretien futur sont pensés au dessin, pas découverts à la première intervention"},{"prestation":"**Calculs** : résistance des matériaux, structure, thermique, sollicitations dynamiques, comportement vibratoire des machines tournantes","benefice":"Les problèmes se voient sur le calcul, pas sur la première pièce. Une reprise de fabrication coûte bien plus cher qu''une note de calcul"},{"prestation":"**Dossier de fabrication** : plans d''ensemble et de détail, nomenclatures, spécifications, notices","benefice":"Vous consultez les ateliers de votre choix. Nous ne vendons ni machine ni composant, aucune marge cachée sur les pièces"},{"prestation":"**Suivi de réalisation et réception** chez les ateliers retenus","benefice":"Les écarts se traitent avant le montage, pas pendant"},{"prestation":"**Montage et mise en service** par nos propres équipes techniques","benefice":"Le même groupe porte le projet du plan à la machine qui tourne. Plus de renvoi de responsabilité entre celui qui conçoit, celui qui fabrique et celui qui pose"}],"prose":[{"texte":"<!-- BLOC C02 : bloc d''offre, prestations et bénéfices côte à côte -->"},{"texte":"Notre équipe d''études couvre **la mécanique, l''électronique et le pneumatique**. C''est son périmètre réel, et nous préférons l''écrire plutôt que de le laisser deviner. Un bureau d''études industriel qui annonce dix compétences en tient rarement trois."}]},{"type":"deroule","etapes":[{"titre":"Votre appel ou votre formulaire.","texte":"Un interlocuteur technique vous rappelle dans l''heure pour comprendre le besoin, pas pour remplir une fiche."},{"titre":"Cadrage et faisabilité.","texte":"Usage, contraintes d''exploitation, environnement, budget, jalons. Sortie : un cahier des charges écrit."},{"titre":"Conception.","texte":"L''avant-projet compare plusieurs solutions. La conception détaillée fige la géométrie, les matériaux et les composants."},{"titre":"Calculs.","texte":"Dimensionnement vérifié, notes de calcul documentées. Essai ciblé quand un point sensible le justifie."},{"titre":"Dossier de fabrication.","texte":"Plans, nomenclatures, spécifications, notices. De quoi consulter et comparer."},{"titre":"Réalisation et réception.","texte":"Suivi de production chez les ateliers, réception des pièces avant montage."},{"titre":"Montage et mise en service.","texte":"Intégration dans votre ligne par nos équipes techniques, jusqu''à la production stabilisée."}]},{"type":"garanties","puces":[{"accroche":"Un rappel dans l''heure","texte":"du lundi au vendredi, 8h00 à 18h30, au 04 78 33 72 05, et une astreinte 24/24 et 7/7 pendant les phases de réalisation."},{"accroche":"Un chef de projet identifié","texte":", votre contact unique du cadrage à la réception, qui mobilise les compétences au fil du projet sans vous renvoyer d''un service à l''autre."},{"accroche":"Des compétences évaluées","texte":"comme nos techniciens, les membres de l''équipe d''études passent un entretien technique et comportemental à l''entrée. Seuls 10 % des candidats sont retenus, et les résultats de l''évaluation vous sont communiqués."}]},{"type":"cta","question":"Besoin de savoir ce que coûterait votre étude avant d''aller plus loin ?","bouton":"Faire chiffrer mon étude","href":"/contact/","rappel":"04 78 33 72 05, rappel dans l''heure"},{"type":"preuves","preuves":[{"titre":"[Étude de cas JOINT LYONNAIS : défaillances machines](/preuves/joint-lyonnais/) · Lyon, depuis février 2024. Diagnostic technique puis plusieurs solutions chiffrées, arbitrées par le client selon son budget."},{"titre":"[Étude de cas ORTHUS x ECOCEM : nouveau site](/preuves/orthus-ecocem/) · Pilotage complet de la construction d''un site industriel de recherche et développement près de Paris, coordination multi-métiers et jalons tenus."},{"titre":"[Étude de cas EATON : mise en production](/preuves/eaton-mise-en-production/) · Janvier 2023. Six techniciens multidisciplinaires pour l''installation et la mise en production d''un parc machines neuf."},{"titre":"[Étude de cas ORTHUS x WASHTEC : installation de stations](/preuves/orthus-washtec/) · Montage des portiques de lavage selon les standards du constructeur, réception, levage et raccordements, partout en France."},{"titre":"[Étude de cas AKTID : montage d''un centre logistique](/preuves/aktid-centre-logistique/) · Montage d''équipements sur un centre logistique, en coordination avec le calendrier du chantier."}]},{"type":"objections","questions":[{"question":"Combien coûte une étude mécanique ?","reponse":"Chaque mission est chiffrée sur devis, sur la base d''un périmètre écrit. Pas d''heures de dessin vendues au kilomètre. Un petit projet bien cadré reste un petit budget."},{"question":"Pouvez-vous reprendre une étude commencée ailleurs ?","reponse":"Oui. Nous repartons de vos fichiers et de vos documents, nous vérifions les hypothèses de dimensionnement, et nous chiffrons la suite. Vos plans restent vos plans."},{"question":"Concevez-vous des machines entières ?","reponse":"Non. Notre acte est l''étude des pièces, des sous-ensembles et des circuits, puis le montage et la mise en service. Un bureau d''étude industriel qui promet tout à tout le monde vous coûte plus cher qu''un périmètre honnête."},{"question":"Qui conçoit réellement mon projet ?","reponse":"Des ingénieurs et des projeteurs salariés, évalués en entretien technique et comportemental : 10 % des candidats retenus. Nos études ne sortent pas de bureaux où l''on n''a jamais serré un boulon."},{"question":"Pouvez-vous rédiger seulement le cahier des charges ?","reponse":"Oui, c''est une mission à part entière : définition du besoin, rédaction, consultation des fournisseurs, analyse des offres. Vous restez libre de confier la suite à qui vous voulez, y compris à un concurrent."},{"question":"Intervenez-vous partout en France ?","reponse":"Oui. Quatre agences, Lyon (siège), Montréal, Dubaï, Madrid, et des hubs de techniciens dans les grandes villes de France. Le siège du groupe est à Limonest, près de Lyon."}]},{"type":"ctaFinal","question":"Besoin d''un interlocuteur technique qui comprenne votre projet dès le premier appel ?","bouton":"Faire chiffrer mon étude","href":"/contact/","rappel":"04 78 33 72 05"}]}'::jsonb where path = '/bureau-etudes/';
